INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('fault:FAULT31-001','fault','Płyta główna / VRM','Diagnostyka sekcji zasilania CPU (VRM)','CPU VRM power-stage diagnostics','symptom: PC wyłącza się pod obciążeniem, CPU nie osiąga deklarowanych zegarów lub płyta nie przechodzi POST. focus: Analiza wejścia EPS, kontrolera PWM, faz zasilania, MOSFET-ów i cewek na podstawie schematu konkretnej płyty. causes: Oddziel brak sygnału EN/PWRGOOD, ograniczenie termiczne, przeciążenie i problem firmware. Odczytaj logi i porównaj zachowanie na ustawieniach domyślnych. checks: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Oddziel brak sygnału EN/PWRGOOD, ograniczenie termiczne, przeciążenie i problem firmware. Odczytaj logi i porównaj zachowanie na ustawieniach domyślnych. steps: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Oddziel brak sygnału EN/PWRGOOD, ograniczenie termiczne, przeciążenie i problem firmware. Odczytaj logi i porównaj zachowanie na ustawieniach domyślnych. 6. Wykonaj test porównawczy lub izolacyjny, zmieniając jeden czynnik. 7. Zastosuj rozwiązanie wyłącznie po potwierdzeniu: Naprawa ma wynikać z pomiarów kontrolera, przebiegu zasilania i oględzin elementów; wymieniaj tylko potwierdzony uszkodzony element. 8. Wykonaj test końcowy, sprawdź funkcje pokrewne i sporządź raport. tests: 1. Odtwórz objaw. 2. Wykonaj test funkcji powiązanych. 3. Sprawdź stabilność i logi. 4. Potwierdź brak nowych błędów. repair: Naprawa ma wynikać z pomiarów kontrolera, przebiegu zasilania i oględzin elementów; wymieniaj tylko potwierdzony uszkodzony element. verify: Testuj w warunkach klienta, zapisz wyniki i sprawdź wszystkie funkcje dotknięte demontażem. stop: Nie wykonuj pomiarów po stronie sieciowej PSU. Pomiary na pracującej płycie wymagają kwalifikacji, sond zabezpieczonych i dokumentacji.','symptomEn: Reported issue: Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. Record when it occurs and whether it is reproducible. focusEn: Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. causesEn: Possible diagnostic areas: Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. Test each hypothesis separately before replacing hardware. checksEn: 1. Confirm the exact model/revision. 2. Record the symptom and operating conditions. 3. Protect customer data. 4. Inspect connectors and visible damage. 5. Compare findings with the correct OEM documentation. stepsEn: 1. Confirm the model, part number and revision. 2. Record the symptom and reproduction conditions. 3. Protect customer data and obtain consent. 4. Inspect connectors and cables safely. 5. Isolate the diagnostic hypothesis with one change at a time. 6. Review logs, firmware and measurements. 7. Repair only after the cause is confirmed. 8. Repeat the original test and document results. testsEn: 1. Reproduce the symptom. 2. Test related functions. 3. Check stability and logs. 4. Confirm no new faults. repairEn: Repair only after a repeatable test confirms the cause. Analyse EPS input, PWM controller, power phases, MOSFETs and inductors using the exact board schematic. Use a replacement part matched to the exact model and revision. verifyEn: Repeat the original customer scenario, test related functions, record results and note any test not performed. stopEn: Stop for smoke, burning smell, liquid damage, swollen battery, exposed mains voltage or an unidentified short. Do not guess pinouts or override encryption.','',''),
('fault:FAULT31-002','fault','GPU / grafika','Diagnostyka braku obrazu z dedykowanej karty GPU','Dedicated GPU no-display diagnostics','symptom: Wentylatory ruszają, ale monitor nie wykrywa sygnału; system może uruchamiać się w tle. focus: Oddziel usterkę karty, slotu PCIe, przewodu obrazu, monitora, firmware i sterownika. causes: Sprawdź POST/debug LED, wyjście płyty, inny przewód i ekran oraz wykrycie urządzenia w systemie. checks: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Sprawdź POST/debug LED, wyjście płyty, inny przewód i ekran oraz wykrycie urządzenia w systemie. steps: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Sprawdź POST/debug LED, wyjście płyty, inny przewód i ekran oraz wykrycie urządzenia w systemie. 6. Wykonaj test porównawczy lub izolacyjny, zmieniając jeden czynnik. 7. Zastosuj rozwiązanie wyłącznie po potwierdzeniu: Dopiero po izolacji przyczyny wykonaj kontrolę złącza, zasilania PCIe i test karty w zgodnym, sprawnym zestawie. 8. Wykonaj test końcowy, sprawdź funkcje pokrewne i sporządź raport. tests: 1. Odtwórz objaw. 2. Wykonaj test funkcji powiązanych. 3. Sprawdź stabilność i logi. 4. Potwierdź brak nowych błędów. repair: Dopiero po izolacji przyczyny wykonaj kontrolę złącza, zasilania PCIe i test karty w zgodnym, sprawnym zestawie. verify: Testuj w warunkach klienta, zapisz wyniki i sprawdź wszystkie funkcje dotknięte demontażem. stop: Nie wkładaj i nie wyjmuj GPU przy zasilonym komputerze; nie dotykaj styków ani nie zwieraj pinów slotu.','symptomEn: Reported issue: Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. Record when it occurs and whether it is reproducible. focusEn: Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. causesEn: Possible diagnostic areas: Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. Test each hypothesis separately before replacing hardware. checksEn: 1. Confirm the exact model/revision. 2. Record the symptom and operating conditions. 3. Protect customer data. 4. Inspect connectors and visible damage. 5. Compare findings with the correct OEM documentation. stepsEn: 1. Confirm the model, part number and revision. 2. Record the symptom and reproduction conditions. 3. Protect customer data and obtain consent. 4. Inspect connectors and cables safely. 5. Isolate the diagnostic hypothesis with one change at a time. 6. Review logs, firmware and measurements. 7. Repair only after the cause is confirmed. 8. Repeat the original test and document results. testsEn: 1. Reproduce the symptom. 2. Test related functions. 3. Check stability and logs. 4. Confirm no new faults. repairEn: Repair only after a repeatable test confirms the cause. Separate GPU, PCIe slot, display cable, monitor, firmware and driver faults. Use a replacement part matched to the exact model and revision. verifyEn: Repeat the original customer scenario, test related functions, record results and note any test not performed. stopEn: Stop for smoke, burning smell, liquid damage, swollen battery, exposed mains voltage or an unidentified short. Do not guess pinouts or override encryption.','',''),
('fault:FAULT31-003','fault','GPU / grafika','Artefakty obrazu i niestabilność pamięci VRAM','Display artifacts and VRAM instability','symptom: Kolorowe bloki, migotanie, błędy tekstur, reset sterownika lub czarny ekran. focus: Rozpoznawanie artefaktów zależnych od temperatury, obciążenia, sterownika i połączenia wyświetlacza. causes: Zapisz, czy artefakt występuje w BIOS, na pulpicie, w zrzucie ekranu i na innym monitorze. Porównaj temperatury oraz logi. checks: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Zapisz, czy artefakt występuje w BIOS, na pulpicie, w zrzucie ekranu i na innym monitorze. Porównaj temperatury oraz logi. steps: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Zapisz, czy artefakt występuje w BIOS, na pulpicie, w zrzucie ekranu i na innym monitorze. Porównaj temperatury oraz logi. 6. Wykonaj test porównawczy lub izolacyjny, zmieniając jeden czynnik. 7. Zastosuj rozwiązanie wyłącznie po potwierdzeniu: Przyczynę potwierdź powtarzalnym testem; sterownik, przewód lub monitor wyklucz przed podejrzeniem VRAM. 8. Wykonaj test końcowy, sprawdź funkcje pokrewne i sporządź raport. tests: 1. Odtwórz objaw. 2. Wykonaj test funkcji powiązanych. 3. Sprawdź stabilność i logi. 4. Potwierdź brak nowych błędów. repair: Przyczynę potwierdź powtarzalnym testem; sterownik, przewód lub monitor wyklucz przed podejrzeniem VRAM. verify: Testuj w warunkach klienta, zapisz wyniki i sprawdź wszystkie funkcje dotknięte demontażem. stop: Nie używaj długich testów obciążeniowych przy artefaktach, przegrzewaniu lub zapachu spalenizny.','symptomEn: Reported issue: Identify artifacts correlated with temperature, load, driver and display connection. Record when it occurs and whether it is reproducible. focusEn: Identify artifacts correlated with temperature, load, driver and display connection. causesEn: Possible diagnostic areas: Identify artifacts correlated with temperature, load, driver and display connection. Test each hypothesis separately before replacing hardware. checksEn: 1. Confirm the exact model/revision. 2. Record the symptom and operating conditions. 3. Protect customer data. 4. Inspect connectors and visible damage. 5. Compare findings with the correct OEM documentation. stepsEn: 1. Confirm the model, part number and revision. 2. Record the symptom and reproduction conditions. 3. Protect customer data and obtain consent. 4. Inspect connectors and cables safely. 5. Isolate the diagnostic hypothesis with one change at a time. 6. Review logs, firmware and measurements. 7. Repair only after the cause is confirmed. 8. Repeat the original test and document results. testsEn: 1. Reproduce the symptom. 2. Test related functions. 3. Check stability and logs. 4. Confirm no new faults. repairEn: Repair only after a repeatable test confirms the cause. Identify artifacts correlated with temperature, load, driver and display connection. Use a replacement part matched to the exact model and revision. verifyEn: Repeat the original customer scenario, test related functions, record results and note any test not performed. stopEn: Stop for smoke, burning smell, liquid damage, swollen battery, exposed mains voltage or an unidentified short. Do not guess pinouts or override encryption.','',''),
('fault:FAULT31-004','fault','BIOS / firmware','Odtwarzanie BIOS z funkcji Flashback','BIOS recovery using Flashback','symptom: Płyta nie przechodzi POST po przerwanym update albo firmware nie uruchamia konfiguracji. focus: Przygotowanie zgodnego obrazu firmware, nośnika USB, nazwy pliku i sekwencji odzyskiwania według OEM. causes: Ustal dokładny model i rewizję PCB; potwierdź, że dana płyta ma funkcję Flashback i sprawdź jej instrukcję. checks: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Ustal dokładny model i rewizję PCB; potwierdź, że dana płyta ma funkcję Flashback i sprawdź jej instrukcję. steps: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Ustal dokładny model i rewizję PCB; potwierdź, że dana płyta ma funkcję Flashback i sprawdź jej instrukcję. 6. Wykonaj test porównawczy lub izolacyjny, zmieniając jeden czynnik. 7. Zastosuj rozwiązanie wyłącznie po potwierdzeniu: Użyj wyłącznie obrazu z oficjalnej strony dla dokładnej rewizji. Zachowaj stabilne zasilanie i nie przerywaj procesu. 8. Wykonaj test końcowy, sprawdź funkcje pokrewne i sporządź raport. tests: 1. Odtwórz objaw. 2. Wykonaj test funkcji powiązanych. 3. Sprawdź stabilność i logi. 4. Potwierdź brak nowych błędów. repair: Użyj wyłącznie obrazu z oficjalnej strony dla dokładnej rewizji. Zachowaj stabilne zasilanie i nie przerywaj procesu. verify: Testuj w warunkach klienta, zapisz wyniki i sprawdź wszystkie funkcje dotknięte demontażem. stop: Nie flashuj obrazu z podobnego modelu. Nie odłączaj zasilania, gdy dioda wskazuje trwający zapis.','symptomEn: Reported issue: Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. Record when it occurs and whether it is reproducible. focusEn: Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. causesEn: Possible diagnostic areas: Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. Test each hypothesis separately before replacing hardware. checksEn: 1. Confirm the exact model/revision. 2. Record the symptom and operating conditions. 3. Protect customer data. 4. Inspect connectors and visible damage. 5. Compare findings with the correct OEM documentation. stepsEn: 1. Confirm the model, part number and revision. 2. Record the symptom and reproduction conditions. 3. Protect customer data and obtain consent. 4. Inspect connectors and cables safely. 5. Isolate the diagnostic hypothesis with one change at a time. 6. Review logs, firmware and measurements. 7. Repair only after the cause is confirmed. 8. Repeat the original test and document results. testsEn: 1. Reproduce the symptom. 2. Test related functions. 3. Check stability and logs. 4. Confirm no new faults. repairEn: Repair only after a repeatable test confirms the cause. Prepare a compatible firmware image, USB media, filename and recovery sequence according to the OEM. Use a replacement part matched to the exact model and revision. verifyEn: Repeat the original customer scenario, test related functions, record results and note any test not performed. stopEn: Stop for smoke, burning smell, liquid damage, swollen battery, exposed mains voltage or an unidentified short. Do not guess pinouts or override encryption.','',''),
('fault:FAULT31-005','fault','BIOS / UEFI','Analiza ustawień UEFI i kolejności bootowania','UEFI settings and boot-order analysis','symptom: Komunikat no bootable device, zniknięcie wpisu Windows Boot Manager lub pętla firmware. focus: Rozróżnianie UEFI/Legacy, GPT/MBR, Secure Boot, CSM, trybu kontrolera i wpisów boot managera. causes: Zapisz ustawienia przed zmianą; sprawdź wykrywanie dysku i stan partycji bez modyfikowania danych. checks: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Zapisz ustawienia przed zmianą; sprawdź wykrywanie dysku i stan partycji bez modyfikowania danych. steps: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Zapisz ustawienia przed zmianą; sprawdź wykrywanie dysku i stan partycji bez modyfikowania danych. 6. Wykonaj test porównawczy lub izolacyjny, zmieniając jeden czynnik. 7. Zastosuj rozwiązanie wyłącznie po potwierdzeniu: Przywracaj ustawienia pojedynczo i zgodnie z pierwotnym sposobem instalacji systemu. 8. Wykonaj test końcowy, sprawdź funkcje pokrewne i sporządź raport. tests: 1. Odtwórz objaw. 2. Wykonaj test funkcji powiązanych. 3. Sprawdź stabilność i logi. 4. Potwierdź brak nowych błędów. repair: Przywracaj ustawienia pojedynczo i zgodnie z pierwotnym sposobem instalacji systemu. verify: Testuj w warunkach klienta, zapisz wyniki i sprawdź wszystkie funkcje dotknięte demontażem. stop: Nie przełączaj AHCI/RAID/VMD ani Secure Boot bez oceny wpływu na rozruch i klucze odzyskiwania.','symptomEn: Reported issue: Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. Record when it occurs and whether it is reproducible. focusEn: Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. causesEn: Possible diagnostic areas: Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. Test each hypothesis separately before replacing hardware. checksEn: 1. Confirm the exact model/revision. 2. Record the symptom and operating conditions. 3. Protect customer data. 4. Inspect connectors and visible damage. 5. Compare findings with the correct OEM documentation. stepsEn: 1. Confirm the model, part number and revision. 2. Record the symptom and reproduction conditions. 3. Protect customer data and obtain consent. 4. Inspect connectors and cables safely. 5. Isolate the diagnostic hypothesis with one change at a time. 6. Review logs, firmware and measurements. 7. Repair only after the cause is confirmed. 8. Repeat the original test and document results. testsEn: 1. Reproduce the symptom. 2. Test related functions. 3. Check stability and logs. 4. Confirm no new faults. repairEn: Repair only after a repeatable test confirms the cause. Distinguish UEFI/Legacy, GPT/MBR, Secure Boot, CSM, controller mode and boot-manager entries. Use a replacement part matched to the exact model and revision. verifyEn: Repeat the original customer scenario, test related functions, record results and note any test not performed. stopEn: Stop for smoke, burning smell, liquid damage, swollen battery, exposed mains voltage or an unidentified short. Do not guess pinouts or override encryption.','',''),
('fault:FAULT31-006','fault','Firmware / bezpieczeństwo','Diagnostyka TPM 2.0 i Secure Boot','TPM 2.0 and Secure Boot diagnostics','symptom: Windows zgłasza brak TPM, stan Secure Boot jest niepoprawny albo aplikacja nie spełnia wymagań. focus: Weryfikacja stanu TPM, trybu Secure Boot, kluczy platformy i wymagań systemu. causes: Sprawdź `tpm.msc`, msinfo32 i dokumentację UEFI; rozróżnij TPM firmware, dTPM i ustawienia platformy. checks: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Sprawdź `tpm.msc`, msinfo32 i dokumentację UEFI; rozróżnij TPM firmware, dTPM i ustawienia platformy. steps: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Sprawdź `tpm.msc`, msinfo32 i dokumentację UEFI; rozróżnij TPM firmware, dTPM i ustawienia platformy. 6. Wykonaj test porównawczy lub izolacyjny, zmieniając jeden czynnik. 7. Zastosuj rozwiązanie wyłącznie po potwierdzeniu: Ustawienia zmieniaj po kopii kluczy odzyskiwania BitLocker i sprawdzeniu wymagań producenta. 8. Wykonaj test końcowy, sprawdź funkcje pokrewne i sporządź raport. tests: 1. Odtwórz objaw. 2. Wykonaj test funkcji powiązanych. 3. Sprawdź stabilność i logi. 4. Potwierdź brak nowych błędów. repair: Ustawienia zmieniaj po kopii kluczy odzyskiwania BitLocker i sprawdzeniu wymagań producenta. verify: Testuj w warunkach klienta, zapisz wyniki i sprawdź wszystkie funkcje dotknięte demontażem. stop: Nie czyść TPM na urządzeniu użytkownika bez kopii kluczy i zgody — może to uniemożliwić dostęp do danych.','symptomEn: Reported issue: Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. Record when it occurs and whether it is reproducible. focusEn: Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. causesEn: Possible diagnostic areas: Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. Test each hypothesis separately before replacing hardware. checksEn: 1. Confirm the exact model/revision. 2. Record the symptom and operating conditions. 3. Protect customer data. 4. Inspect connectors and visible damage. 5. Compare findings with the correct OEM documentation. stepsEn: 1. Confirm the model, part number and revision. 2. Record the symptom and reproduction conditions. 3. Protect customer data and obtain consent. 4. Inspect connectors and cables safely. 5. Isolate the diagnostic hypothesis with one change at a time. 6. Review logs, firmware and measurements. 7. Repair only after the cause is confirmed. 8. Repeat the original test and document results. testsEn: 1. Reproduce the symptom. 2. Test related functions. 3. Check stability and logs. 4. Confirm no new faults. repairEn: Repair only after a repeatable test confirms the cause. Verify TPM state, Secure Boot mode, platform keys and operating-system requirements. Use a replacement part matched to the exact model and revision. verifyEn: Repeat the original customer scenario, test related functions, record results and note any test not performed. stopEn: Stop for smoke, burning smell, liquid damage, swollen battery, exposed mains voltage or an unidentified short. Do not guess pinouts or override encryption.','',''),
('fault:FAULT31-007','fault','Laptop / EC','Diagnostyka kontrolera EC/KBC','Embedded Controller (EC/KBC) diagnostics','symptom: Brak reakcji przycisku, nietypowe diody, brak ładowania lub nieregularny start. focus: Rozpoznawanie objawów związanych z kontrolerem klawiatury, przyciskiem Power, ładowaniem i sekwencją startową. causes: Sprawdź złącza, przycisk, baterię, adapter i kody POST; odczyty linii EC wykonuj tylko według schematu. checks: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Sprawdź złącza, przycisk, baterię, adapter i kody POST; odczyty linii EC wykonuj tylko według schematu. steps: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Sprawdź złącza, przycisk, baterię, adapter i kody POST; odczyty linii EC wykonuj tylko według schematu. 6. Wykonaj test porównawczy lub izolacyjny, zmieniając jeden czynnik. 7. Zastosuj rozwiązanie wyłącznie po potwierdzeniu: Weryfikuj firmware EC i procedurę producenta; programowanie układu powierz technikowi z właściwym sprzętem. 8. Wykonaj test końcowy, sprawdź funkcje pokrewne i sporządź raport. tests: 1. Odtwórz objaw. 2. Wykonaj test funkcji powiązanych. 3. Sprawdź stabilność i logi. 4. Potwierdź brak nowych błędów. repair: Weryfikuj firmware EC i procedurę producenta; programowanie układu powierz technikowi z właściwym sprzętem. verify: Testuj w warunkach klienta, zapisz wyniki i sprawdź wszystkie funkcje dotknięte demontażem. stop: Nie zwieraj pinów EC ani nie wgrywaj wsadu z innej rewizji płyty.','symptomEn: Reported issue: Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. Record when it occurs and whether it is reproducible. focusEn: Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. causesEn: Possible diagnostic areas: Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. Test each hypothesis separately before replacing hardware. checksEn: 1. Confirm the exact model/revision. 2. Record the symptom and operating conditions. 3. Protect customer data. 4. Inspect connectors and visible damage. 5. Compare findings with the correct OEM documentation. stepsEn: 1. Confirm the model, part number and revision. 2. Record the symptom and reproduction conditions. 3. Protect customer data and obtain consent. 4. Inspect connectors and cables safely. 5. Isolate the diagnostic hypothesis with one change at a time. 6. Review logs, firmware and measurements. 7. Repair only after the cause is confirmed. 8. Repeat the original test and document results. testsEn: 1. Reproduce the symptom. 2. Test related functions. 3. Check stability and logs. 4. Confirm no new faults. repairEn: Repair only after a repeatable test confirms the cause. Recognise symptoms involving keyboard controller, power button, charging and startup sequencing. Use a replacement part matched to the exact model and revision. verifyEn: Repeat the original customer scenario, test related functions, record results and note any test not performed. stopEn: Stop for smoke, burning smell, liquid damage, swollen battery, exposed mains voltage or an unidentified short. Do not guess pinouts or override encryption.','',''),
('fault:FAULT31-008','fault','Bateria / zasilanie','Ocena kondycji baterii laptopa','Laptop battery health assessment','symptom: Krótki czas pracy, nagłe wyłączenie, brak ładowania lub komunikat o niewykrytej baterii. focus: Analiza pojemności projektowej i pełnego ładowania, cykli, napięcia, temperatury i komunikacji BMS. causes: Porównaj raport systemu z diagnostyką OEM, sprawdź zasilacz i zachowanie na zasilaniu sieciowym. checks: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Porównaj raport systemu z diagnostyką OEM, sprawdź zasilacz i zachowanie na zasilaniu sieciowym. steps: 1. Potwierdź model, numer części i rewizję płyty/urządzenia. 2. Zapisz objaw, czas wystąpienia i warunki odtworzenia. 3. Zabezpiecz dane i uzyskaj zgodę na diagnostykę. 4. Wykonaj oględziny i kontrolę przewodów/złączy bez ryzykownego zasilania. 5. Zweryfikuj hipotezę: Porównaj raport systemu z diagnostyką OEM, sprawdź zasilacz i zachowanie na zasilaniu sieciowym. 6. Wykonaj test porównawczy lub izolacyjny, zmieniając jeden czynnik. 7. Zastosuj rozwiązanie wyłącznie po potwierdzeniu: Wymieniaj baterię tylko na zgodny, certyfikowany moduł; po wymianie wykonaj kalibrację, jeśli zaleca ją producent. 8. Wykonaj test końcowy, sprawdź funkcje pokrewne i sporządź raport. tests: 1. Odtwórz objaw. 2. Wykonaj test funkcji powiązanych. 3. Sprawdź stabilność i logi. 4. Potwierdź brak nowych błędów. repair: Wymieniaj baterię tylko na zgodny, certyfikowany moduł; po wymianie wykonaj kalibrację, jeśli zaleca ją producent. verify: Testuj w warunkach klienta, zapisz wyniki i sprawdź wszystkie funkcje dotknięte demontażem. stop: Spuchniętej, przebitej lub przegrzewającej się baterii nie naciskaj, nie przebijaj ani nie ładuj.','symptomEn: Reported issue: Analyse design/full-charge capacity,